// Test Suite for U06_2, UC-14, VIRTUA-2.4-1, 2.4-2, 2.4-3, 2.4-4, 2.5-1

// Lab Incharge Tests
[Test]
public void TestLabInchargePerformsLabTestsAndUpdatesReports()
{
    // Arrange
    var labIncharge = new LabIncharge();
    var report = new Report();

    // Act
    labIncharge.PerformLabTests();
    labIncharge.UpdateReport(report);

    // Assert
    Assert.AreEqual(true, report.IsUpdated);
}

[Test]
public void TestLabInchargeSetsFlagInPrescription()
{
    // Arrange
    var labIncharge = new LabIncharge();
    var prescription = new Prescription();

    // Act
    labIncharge.SetFlagInPrescription(prescription);

    // Assert
    Assert.AreEqual(true, prescription.HasFlag);
}

// Chemist Tests
[Test]
public void TestChemistDeliversMedicineOffline()
{
    // Arrange
    var chemist = new Chemist();
    var patient = new Patient();

    // Act
    chemist.DeliverMedicine(patient);

    // Assert
    Assert.AreEqual(true, patient.HasMedicine);
}

[Test]
public void TestChemistSetsFlagInPrescription()
{
    // Arrange
    var chemist = new Chemist();
    var prescription = new Prescription();

    // Act
    chemist.SetFlagInPrescription(prescription);

    // Assert
    Assert.AreEqual(true, prescription.HasFlag);
}

// Admin Tests
[Test]
public void TestAdminViewsInvoiceAndReports()
{
    // Arrange
    var admin = new Admin();
    var patient = new Patient();
    var report = new Report();

    // Act
    admin.ViewInvoiceAndReports(patient, report);

    // Assert
    Assert.AreEqual(true, report.IsViewed);
}

// System Deployment Tests
[Test]
public void TestSystemDeployedOnHeroku()
{
    // Arrange
    var system = new System();

    // Act
    system.DeployOnHeroku();

    // Assert
    Assert.IsTrue(system.IsDeployedOnHeroku);
}

// System Access Tests
[Test]
public void TestSystemAccessedMultipleBrowsers()
{
    // Arrange
    var system = new System();

    // Act
    system.AccessOnMultipleBrowsers();

    // Assert
    Assert.IsTrue(system.IsAccessibleOnMultipleBrowsers);
}

// Operating System Tests
[Test]
public void TestOperatingSystemCompatibility()
{
    // Arrange
    var system = new System();
    var os = new OperatingSystem();

    // Act
    system.SetOperatingSystemCompatibility(os);

    // Assert
    Assert.IsTrue(system.IsCompatibleWith(os));
}

// Report Printing Tests
[Test]
public void TestPrintPrescriptionAndInvoice()
{
    // Arrange
    var report = new Report();

    // Act
    report.Print();

    // Assert
    Assert.IsTrue(report.IsPrinted);
}

// Patient Consultation Request Tests
[Test]
public void TestPreventFullScanOfPatientConsultationRequest()
{
    // Arrange
    var system = new System();
    var patientConsultationRequest = new PatientConsultationRequest();

    // Act
    system.PreventFullScan(patientConsultationRequest);

    // Assert
    Assert.IsTrue(patientConsultationRequest.IsPartialScan);
}
